play:none}.shareIcon.facebook{flex-grow:1}.shareIcon.facebook a:after{content:attr(data-text);display:block}.shareInner{align-items:flex-end}.shareIn:checked~.shareInner .shareBlock{border-radius:15px 15px 0 0}} @media only screen and (max-width:380px){#featured .widget.PopularPosts .widget-content{min-height:180px}.featured-item{height:180px}.block-left .entry-image-wrap{height:180px}.grid-item .entry-title,.related-item .entry-title,.video-item .entry-title{font-size:14px}.item-post h1.entry-title{font-size:27px}.item-post .entry-meta .align-right{display:none}.tocify-inner{min-width:100%}.vtrick-pro-share-links li.has-span a{width:34px;justify-content:center}.vtrick-pro-share-links li.has-span a:before{background-color:transparent;padding:0}.mini-item .entry-image-wrap{height:95px}.mini-item .entry-title{font-size:14px}.FeaturedPost .featured-post{height:180px}} @media only screen and (max-width:340px){#slide-menu{width:100%}.errorWrap h3{font-size:110px}.errorWrap h4{font-size:27px}}
/*! Scroll bar */ ::-webkit-scrollbar-track{background-color:var(--outer-bg)}::-webkit-scrollbar-thumb{-webkit-border-radius:.5625rem;border-radius:.5625rem;border:.375rem solid transparent;background-color:var(--scroll-bg);background-clip:padding-box}::-webkit-scrollbar-corner{background-color:var(--outer-bg)}::-webkit-scrollbar{width:1.25rem;background-color:var(--outer-bg)}
/* 글 제목1,2,3 스타일 - 본문 안에서만 */
.post-body h2 { color: #1a1a2e; font-size: 1.6em; font-weight: 700; letter-spacing: -0.01em; margin: 48px 0 20px 0; line-height: 1.4; position: relative; padding-bottom: 12px; }
.post-body h2::after { content: ""; position: absolute; left: 0; bottom: 0; width: 40px; /* 전체가 아닌 짧은 밑줄 */ height: 4px; border-radius: 2px; background: #4f7cff; /* 포인트 컬러 하나만 */ }
/* 메인 히어로 전체폭 */ #hero-wrapper { padding: 0 !important; }
#hero-wrapper > .container.row-x1 { max-width: 100% !important; }
#hero-post { max-width: 100% !important; }
/* HM 게시물 카드 PC - 힐링K 스타일 */ .index-post-wrap { grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)) !important; gap: 20px !important; }
.index-post .entry-title, .index-post .entry-title a { font-size: 1rem !important; line-height: 1.4 !important; letter-spacing: normal !important; margin: 0 0 8px !important; color: #000 !important; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.index-post .entry-header { padding: 14px 16px !important; }
.index-post .entry-excerpt { font-size: 0.87rem !important; line-height: 1.5 !important; color: #555 !important; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
/* HM 게시물 카드 - PC (힐링K 스타일) */ .index-post-wrap { grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)) !important; gap: 20px !important; }
.index-post .entry-title, .index-post .entry-title a { font-size: 1rem !important; line-height: 1.4 !important; letter-spacing: normal !important; margin: 0 0 8px !important; color: #000 !important; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.index-post .entry-header { padding: 14px 16px !important; }
.index-post .entry-excerpt { font-size: 0.87rem !important; line-height: 1.5 !important; color: #555 !important; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
/* HM 게시물 카드 - 모바일 2열 */ @media (max-width: 768px) { .blog-posts-wrap .index-post-wrap { display: flex !important; flex-wrap: wrap !important; gap: 10px !important; justify-content: space-between; width: 100%; padding: 0; margin: 0; box-sizing: border-box; }
.blog-posts-wrap .index-post { flex-basis: calc(50% - 5px) !important; width: calc(50% - 5px) !important; max-width: calc(50% - 5px) !important; margin: 0 !important; box-sizing: border-box; background-color: #fff; border-radius: 8px; box-shadow: 0 2px 5px rgba(0, 0, 0, 0.05); overflow: hidden; display: flex; flex-direction: column; }
.index-post .entry-header { padding: 10px 12px !important; flex-grow: 1; display: flex; flex-direction: column; }
.index-post .entry-title, .index-post .entry-title a { font-size: 1rem !important; line-height: 1.3; margin-bottom: 6px; min-height: 2.6em; height: auto; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.index-post .entry-excerpt, .index-post .post-snippet { display: none !important; } }
@media (max-width: 480px) { .blog-posts-wrap .index-post-wrap { gap: 8px !important; } .blog-posts-wrap .index-post { flex-basis: calc(50% - 4px) !important; width: calc(50% - 4px) !important; max-width: calc(50% - 4px) !important; } .index-post .entry-header { padding: 8px 10px !important; } .index-post .entry-title, .index-post .entry-title a { font-size: 1.1rem !important; margin-bottom: 4px; min-height: 2.4em; height: auto; line-height: 1.2; } }
/* HM 게시물 카드 - 날짜 스타일 */ .index-post .author-row { font-size: 0.75rem !important; color: #999 !important; margin-top: auto !important; padding-top: 10px !important; border-top: 1px solid #f0f0f0; display: flex; align-items: center; }
.index-post .author-row .published, .index-post .author-row time { font-size: 0.75rem !important; color: #999 !important; font-weight: 400 !important; letter-spacing: 0.2px; }
/* 댓글 카운트 오른쪽 정렬 */ .index-post .cmt-count { font-size: 0.75rem !important; color: #999 !important; margin-left: auto !important; }
/* 아바타가 남아있다면 작게 (없으면 무시됨) */ .index-post .author-avatar-wrap { width: 18px !important; height: 18px !important; margin-right: 6px !important; border: none !important; }
.index-post .author-name { font-weight: 500 !important; font-size: 0.75rem !important; color: #666 !important; }
/* 구분자 */ .index-post .author-row .on.sp { color: #ccc; padding: 0 4px; }
/* 모바일 카드 - 정사각형 → 5:3 비율 (세로 살짝 축소) */ @media (max-width: 768px) { .index-post .entry-image-wrap { position: relative !important; padding-top: 60% !important; /* 5:3 비율 */ height: 0 !important; overflow: hidden !important; }
.index-post .entry-image-wrap .entry-thumb, .index-post .entry-image-wrap svg { position: absolute !important; top: 0 !important; left: 0 !important; width: 100% !important; height: 100% !important; } }
@media (max-width:768px) { /* 헤더 내부 여백 최소화 */ .index-post .entry-header { padding: 8px 10px !important; gap: 4px !important; }
/* 태그 여백 제거 */ .index-post .entry-tag, .index-post .entry-tags { margin: 0 0 4px !important; padding: 0 !important; line-height: 1.2 !important; }
/* 제목 여백 축소 */ .index-post .entry-title { margin: 0 0 4px !important; line-height: 1.3 !important; }
/* 작성자/날짜 줄 여백 축소 */ .index-post .author-row { margin: 4px 0 0 !important; padding-top: 4px !important; } }
@media (max-width:768px) { /* 카드 그리드: 모바일 간격 정리 */ .blog-posts-wrap .index-post-wrap { gap: 20px !important; padding: 0 10px !important; margin: 0 !important; }
.blog-posts-wrap .index-post { flex-basis: calc(50% - 10px) !important; width: calc(50% - 10px) !important; max-width: calc(50% - 10px) !important; } }
@media (max-width:480px) { .blog-posts-wrap .index-post-wrap { gap: 16px !important; padding: 0 8px !important; } .blog-posts-wrap .index-post { flex-basis: calc(50% - 8px) !important; width: calc(50% - 8px) !important; max-width: calc(50% - 8px) !important; } }
.dark-mode-toggle, .theme-toggle, [class*="dark"][class*="toggle"], #darkModeToggle { display: none !important; }
/* 테마의 구형 SNS 공유 버튼 제거 */ .post-share, .vtrick-pro-share-links, .shareInner, .shareBlock { display: none !important; }
/* 기존 게시글 인라인 SNS 공유 버튼 숨김 */ .sns-go, .sns-buttons, .healingk-share-widget-container, .healingk-disclaimer { display: none !important; }/* X / Threads 아이콘 - Bootstrap Icons font (SVG data URI 제거) */ .social .X a:before, .social a.X:before{content:"\f8db";} .social .Threads a:before, .social a.Threads:before{content:"\f8d9";} #LinkList103 a.X,#LinkList103 a.Threads{background-image:none!important;} #LinkList103 a.X:before,#LinkList103 a.Threads:before{display:inline-block!important;font-family:bootstrap-icons!important;font-style:normal!important;font-weight:400!important;font-variant:normal!important;text-transform:none!important;line-height:1!important;-webkit-font-smoothing:antialiased;-moz-osx-font-smoothing:grayscale;}
/* ====================================================== Healing-Mart TOC v3 2026 Minimal Design ====================================================== */ /* HealingMart 목차 전체 영역 */ .hm-toc-wrap { margin: 24px 0; border: 1px solid #e7edf4; border-radius: 18px; background: #ffffff; box-shadow: 0 1px 2px rgba(0, 0, 0, 0.03); overflow: hidden; transition: border-color 0.2s ease; }
.hm-toc-wrap:hover { border-color: #d7e2ee; }
/* 목차 상단 헤더 */ .hm-toc-header { width: 100%; display: flex; align-items: center; gap: 12px; padding: 12px 18px; background: #ffffff; border: 0; border-bottom: 1px solid #eef2f7; cursor: pointer; font: inherit; text-align: left; }
/* 목차 아이콘 */ .hm-toc-icon { width: 32px; height: 32px; display: flex; align-items: center; justify-content: center; border-radius: 50%; background: #f8fafc; color: #0f172a; flex: none; }
/* 목차 제목 영역 */ .hm-toc-title { flex: 1; display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.hm-toc-title strong { font-size: 17px; font-weight: 700; line-height: 1.4; color: #0f172a; }
.hm-toc-count { font-size: 13px; line-height: 1.4; color: #94a3b8; font-weight: 400; }
/* 펼치기·접기 아이콘 */ .hm-toc-toggle { color: #94a3b8; transition: transform 0.25s ease; font-size: 13px; flex: none; }
.hm-toc-wrap.is-open .hm-toc-toggle { transform: rotate(180deg); }
/* 펼쳐지는 목차 본문 */ .hm-toc-body { max-height: 0; overflow: hidden; transition: max-height 0.35s ease; background: #ffffff; }
/* 목차 목록 */ .hm-toc-list { list-style: none; margin: 0; padding: 12px 18px 16px; }
/* 목차 항목 */ .hm-toc-item { display: flex; align-items: flex-start; gap: 12px; padding: 7px 0; }
/* 목차 번호 */ .hm-toc-num { min-width: 24px; color: #64748b; font-size: 13px; font-weight: 700; line-height: 1.7; flex: none; margin-top: 0; }
/* 목차 링크 */ .hm-toc-link { flex: 1; color: #334155 !important; font-size: 15px !important; line-height: 1.7 !important; text-decoration: none !important; overflow-wrap: break-word; transition: color 0.15s ease; }
.hm-toc-link:hover { color: #0f172a !important; text-decoration: underline !important; text-underline-offset: 3px; }
/* H3 목차 항목 */ .hm-toc-h3 { padding-left: 18px; }
.hm-toc-h3 .hm-toc-link { font-size: 14px !important; color: #64748b !important; }
.hm-toc-h3::before { content: ""; width: 5px; height: 5px; background: #cbd5e1; border-radius: 50%; flex: none; margin-top: 11px; }
/* H4 목차 항목 */ .hm-toc-h4 { padding-left: 36px; }
.hm-toc-h4 .hm-toc-link { font-size: 13px !important; color: #94a3b8 !important; }
/* 모바일 */ @media (max-width: 768px) { .hm-toc-wrap { margin: 20px 0; border-radius: 14px; }
.hm-toc-header { gap: 10px; padding: 11px 14px; }
.hm-toc-icon { width: 30px; height: 30px; }
.hm-toc-title strong { font-size: 16px; }
.hm-toc-count { font-size: 12px; }
.hm-toc-list { padding: 10px 14px 14px; }
.hm-toc-item { gap: 10px; padding: 6px 0; }
.hm-toc-link { font-size: 14px !important; }
.hm-toc-h3 { padding-left: 14px; }
.hm-toc-h3 .hm-toc-link { font-size: 13.5px !important; }
.hm-toc-h4 { padding-left: 28px; }
.hm-toc-h4 .hm-toc-link { font-size: 13px !important; } }
/* ======================================== 게시물 하단 통합 카드 - 공유 - 이용안내 · 저작권 · 오류신고 ======================================== */
.hm-post-tools { width: calc(100% - 40px); max-width: 1200px; margin: 36px auto 24px; overflow: hidden; background: var(--body-bg-color); border: 1px solid var(--border-color); border-radius: 14px; box-sizing: border-box; box-shadow: 0 8px 24px rgba(15, 23, 42, .05); }
.hm-share-row { display: flex; align-items: center; justify-content: space-between; gap: 20px; padding: 16px 18px; }
.hm-share-copy { display: flex; align-items: center; min-width: 0; gap: 12px; }
.hm-share-symbol { display: inline-flex; flex: 0 0 auto; align-items: center; justify-content: center; width: 34px; height: 34px; background: var(--rgba-gray); border-radius: 50%; }
.hm-share-symbol svg { width: 18px; height: 18px; fill: none; stroke: var(--accent); stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
.hm-share-title { display: flex; min-width: 0; flex-direction: column; gap: 3px; line-height: 1.35; }
.hm-share-title strong { color: var(--title-color); font-size: 15px; font-weight: 700; }
.hm-share-title span { color: var(--meta-color); font-size: 12px; font-weight: 400; }
.hm-share-buttons, .hm-share-more { display: flex; align-items: center; justify-content: center; flex-wrap: wrap; gap: 10px; }
.hm-share-buttons { flex: 0 0 auto; }
.hm-share-more { display: none; justify-content: flex-end; padding: 0 18px 15px; }
.hm-share-more.active { display: flex; }
.hm-btn { display: inline-flex; align-items: center; justify-content: center; width: 42px; height: 42px; padding: 0; border: 0; border-radius: 50%; cursor: pointer; box-shadow: 0 2px 6px rgba(15, 23, 42, .14); transition: transform .18s ease, box-shadow .18s ease, opacity .18s ease; }
.hm-btn svg { width: 21px; height: 21px; }
.hm-btn:hover { transform: translateY(-2px); box-shadow: 0 5px 12px rgba(15, 23, 42, .2); }
.hm-btn:focus-visible { outline: 2px solid #93c5fd; outline-offset: 3px; }
.hm-kakao { background: #FEE500; } .hm-naver { background: #03C75A; } .hm-facebook { background: #1877F2; } .hm-x { background: #000; } .hm-threads { background: #000; } .hm-more { background: #64748b; } .hm-copy { background: #6B7280; } .hm-band { background: #44DA5B; } .hm-telegram { background: #0088CC; }
.hm-info-box { width: 100%; max-width: none; margin: 0; overflow: hidden; background: transparent; border: 0; border-top: 1px solid var(--border-color); border-radius: 0; box-sizing: border-box; }
.hm-info-box summary { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 13px 18px; list-style: none; cursor: pointer; user-select: none; }
.hm-info-box summary::-webkit-details-marker { display: none; }
.hm-info-box summary::marker { display: none; content: ""; }
.hm-info-box summary:focus-visible { outline: 2px solid #93c5fd; outline-offset: -3px; }
.hm-info-left { display: flex; align-items: center; min-width: 0; gap: 10px; }
.hm-info-icon { display: inline-flex; flex: 0 0 auto; align-items: center; justify-content: center; width: 30px; height: 30px; background: var(--rgba-gray); border-radius: 50%; }
.hm-info-icon svg { width: 17px; height: 17px; stroke: var(--accent); stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
.hm-info-title { color: var(--title-color); font-size: 14px; font-weight: 700; line-height: 1.4; }
.hm-arrow { display: inline-flex; flex: 0 0 auto; align-items: center; justify-content: center; width: 20px; height: 20px; transition: transform .2s ease; }
.hm-arrow svg { width: 100%; height: 100%; fill: none; stroke: var(--meta-color); stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
.hm-info-box[open] .hm-arrow { transform: rotate(180deg); }
.hm-info-box[open] summary { border-bottom: 1px solid var(--border-color); }
.hm-info-content { padding: 4px 18px 18px; }
.hm-item { padding: 15px 0; }
.hm-item + .hm-item { border-top: 1px solid var(--border-color); }
.hm-label { display: block; margin: 0 0 8px; color: var(--accent); font-size: 13px; font-weight: 700; line-height: 1.5; letter-spacing: .02em; }
.hm-item p { margin: 0; color: var(--text-color); font-size: 14px; line-height: 1.8; word-break: keep-all; overflow-wrap: break-word; }
.hm-item p + p { margin-top: 10px; }
.hm-info-links { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; }
.hm-info-links a { color: var(--accent); font-weight: 700; }
/* ======================================== 웹도구 전용 1680px 작업영역 - 최대 작업폭 1680px, 화면이 좁으면 100% - 실제 웹도구가 감지된 게시물에만 적용 ======================================== */
body.hm-webtool-page { background: var(--outer-bg) !important; }
body.hm-webtool-page #outer-wrapper, body.hm-webtool-page #content-wrapper, body.hm-webtool-page #main-wrapper, body.hm-webtool-page #main { background-color: var(--outer-bg) !important; }
body.hm-webtool-page #content-wrapper { width: 100% !important; max-width: 1680px !important; margin-left: auto !important; margin-right: auto !important; overflow: visible !important; padding-left: 0 !important; padding-right: 0 !important; padding-bottom: 0 !important; }
body.hm-webtool-page #content-wrapper > .container, body.hm-webtool-page #main-wrapper, body.hm-webtool-page #main, body.hm-webtool-page #main .Blog, body.hm-webtool-page .item-post-wrap, body.hm-webtool-page .item-post-inner { width: 100% !important; max-width: 1680px !important; margin-left: auto !important; margin-right: auto !important; }
body.hm-webtool-page .item-post-inner { padding-left: 0 !important; padding-right: 0 !important; }
body.hm-webtool-page .entry-content-wrap { min-height: calc(100vh - 59px); margin: 0 !important; padding: 0 !important; background: transparent !important; border-radius: 0 !important; box-shadow: none !important; }
body.hm-webtool-page #post-body { float: none !important; min-height: calc(100vh - 59px); }
/* ======================================== 지도/풀화면 서비스 전용 작업영역 - 지도형 서비스: 브라우저 가로폭 100% - 일반 게시물 1500px / 웹도구 1680px 규칙과 완전 분리 ======================================== */ body.hm-map-page, body.hm-fullscreen-page { background: var(--outer-bg) !important; }
body.hm-map-page #outer-wrapper, body.hm-fullscreen-page #outer-wrapper { width: 100% !important; max-width: none !important; overflow: visible !important; }
body.hm-map-page #content-wrapper, body.hm-fullscreen-page #content-wrapper, body.hm-map-page #content-wrapper > .container, body.hm-fullscreen-page #content-wrapper > .container, body.hm-map-page #main-wrapper, body.hm-fullscreen-page #main-wrapper, body.hm-map-page #main, body.hm-fullscreen-page #main, body.hm-map-page #main .Blog, body.hm-fullscreen-page #main .Blog, body.hm-map-page .item-post-wrap, body.hm-fullscreen-page .item-post-wrap, body.hm-map-page .item-post-inner, body.hm-fullscreen-page .item-post-inner, body.hm-map-page .entry-content-wrap, body.hm-fullscreen-page .entry-content-wrap, body.hm-map-page #post-body, body.hm-fullscreen-page #post-body { width: 100% !important; max-width: none !important; margin-left: 0 !important; margin-right: 0 !important; padding-left: 0 !important; padding-right: 0 !important; float: none !important; box-sizing: border-box !important; }
body.hm-map-page #content-wrapper, body.hm-fullscreen-page #content-wrapper { margin: 0 !important; padding-top: 0 !important; padding-bottom: 0 !important; overflow: visible !important; }
body.hm-map-page .entry-content-wrap, body.hm-fullscreen-page .entry-content-wrap { padding-top: 0 !important; padding-bottom: 0 !important; background: transparent !important; border-radius: 0 !important; box-shadow: none !important; }
body.hm-webtool-page .hm-post-tools { margin-left: auto; margin-right: auto; }
@media (max-width: 768px) { .hm-post-tools { max-width: none; margin: 28px 0 20px; border-radius: 12px; }
.hm-share-row { flex-direction: column; align-items: stretch; gap: 14px; padding: 15px 14px; }
.hm-share-copy { justify-content: center; text-align: center; }
.hm-share-buttons { width: 100%; gap: 9px; }
.hm-share-more { justify-content: center; padding: 0 14px 14px; }
.hm-btn { width: 40px; height: 40px; }
.hm-btn svg { width: 20px; height: 20px; }
.hm-info-box summary { gap: 12px; padding: 12px 14px; }
.hm-info-content { padding: 2px 14px 15px; }
.hm-item { padding: 14px 0; }
body.hm-webtool-page #content-wrapper { padding: 0 !important; } }
@media (max-width: 420px) { .hm-share-title span { display: none; }
.hm-share-title strong { font-size: 14px; }
.hm-share-symbol { width: 32px; height: 32px; } }
<!--새로운 애드센스 css -->
.hm-ad-wrap { width: 100%; max-width: 100%; margin: 32px auto; text-align: center; overflow: hidden; padding: 0 10px; /* 좌우 살짝 여백 */ }
/* 광고 자체 */ .hm-ad-wrap .hm-ad-top { display: inline-block !important; margin: 0 auto; max-width: 100%; /* 중요: 넘침 방지 */ }
/* ==================== 모바일 (~499px) ==================== */ @media (max-width: 499px) { .hm-ad-wrap { max-width: 320px; min-height: 100px; margin: 28px auto; padding: 0 8px; }
.hm-ad-top { width: 320px !important; height: 100px !important; } }
/* ==================== 태블릿 & 작은 PC (500px ~ 1024px) ==================== */ @media (min-width: 500px) and (max-width: 1024px) { .hm-ad-wrap { max-width: none; /* 제한 해제 */ padding: 0 16px; }
.hm-ad-top { width: 468px !important; /* 태블릿에 적합한 크기 */ height: 60px !important; max-width: 100% !important; } }
/* ==================== PC (1025px 이상) ==================== */ @media (min-width: 1025px) { .hm-ad-wrap { max-width: none; padding: 0 20px; }
.hm-ad-top { width: 728px !important; height: 90px !important; } }
/* ========================================================= 일반 게시글 상단 대형 광고 전용 기존 웹도구·사이드 광고에는 적용되지 않음 ========================================================= */
/* 모바일 */ @media (max-width: 499px) { .hm-ad-wrap.hm-post-top-ad { width: 320px; max-width: 100%; min-height: 100px; margin: 28px auto; padding: 0; }
.hm-ad-wrap.hm-post-top-ad .hm-ad-top { width: 320px !important; max-width: 100% !important; height: 100px !important; } }
/* 태블릿 */ @media (min-width: 500px) and (max-width: 767px) { .hm-ad-wrap.hm-post-top-ad { width: 468px; max-width: 100%; min-height: 60px; margin: 32px auto; padding: 0; }
.hm-ad-wrap.hm-post-top-ad .hm-ad-top { width: 468px !important; max-width: 100% !important; height: 60px !important; } }
/* 큰 태블릿과 좁은 PC */ @media (min-width: 768px) and (max-width: 1082px) { .hm-ad-wrap.hm-post-top-ad { width: 728px; max-width: 100%; min-height: 90px; margin: 32px auto; padding: 0; }
.hm-ad-wrap.hm-post-top-ad .hm-ad-top { width: 728px !important; max-width: 100% !important; height: 90px !important; } }
/* 넓은 PC */ @media (min-width: 1083px) { .hm-ad-wrap.hm-post-top-ad { width: 1050px; max-width: 100%; min-height: 250px; margin: 32px auto; padding: 0 40px;
display: flex; align-items: center; justify-content: center; box-sizing: border-box; }
.hm-ad-wrap.hm-post-top-ad .hm-ad-top { width: 970px !important; max-width: 100% !important; height: 250px !important; margin: 0 auto !important; } }
/* VTrick 가짜 평점 임시 숨김 */ .post-rating, .post-rating-wrap, .post-rating-info, .rate-wrap, .rating-wrap { display: none !important; }
/* ================================================== HealingMart v28 width policy - 지도/풀화면 서비스: 가로폭 100% - 웹도구/게임 서비스: 최대 1680px - 일반 게시물: 최대 1500px + PC 사이드바 숨김 - 모바일: 사이드바 숨김 ================================================== */
.hm-no-sidebar #sidebar-wrapper, .hm-service-view #sidebar-wrapper, body.is-post #sidebar-wrapper{ display:none !important; }
.hm-no-sidebar #main-wrapper, .hm-service-view #main-wrapper, body.is-post #main-wrapper{ width:100% !important; }
.hm-no-sidebar #content-wrapper > .container, .hm-service-view #content-wrapper > .container, body.is-post #content-wrapper > .container{ justify-content:center !important; }
/* 일반 정보 게시물: 1500px 프레임. 웹도구는 아래 1680px 규칙이 우선한다. */ body.is-post:not(.hm-webtool-page):not(.hm-map-page):not(.hm-fullscreen-page) #content-wrapper{ width:100% !important; max-width:1500px !important; margin-left:auto !important; margin-right:auto !important; }
body.is-post:not(.hm-webtool-page):not(.hm-map-page):not(.hm-fullscreen-page) #content-wrapper > .container, body.is-post:not(.hm-webtool-page):not(.hm-map-page):not(.hm-fullscreen-page) #main-wrapper, body.is-post:not(.hm-webtool-page):not(.hm-map-page):not(.hm-fullscreen-page) #main{ width:100% !important; max-width:1500px !important; }
@media only screen and (max-width:980px){ #sidebar-wrapper{display:none !important} #main-wrapper{width:100% !important} #content-wrapper > .container{justify-content:center !important} }
/* 게시글 제목·작성자 영역을 사용하지 않을 때 상단 빈 공간 제거 */ .is-single .item-post .blog-entry-header { display: none !important; height: 0 !important; min-height: 0 !important; margin: 0 !important; padding: 0 !important; }
/* 게시글 본문 상단 여백 축소 */ .is-single .entry-content-wrap { margin-top: 0 !important; padding-top: 1.5rem !important; }
/* 모바일 */ @media only screen and (max-width: 680px) { .is-single .entry-content-wrap { margin-top: 0 !important; padding-top: 1rem !important; } }
/* HM RELATED POSTS: keep the theme's original responsive card size and center only the actual cards on PC */ @media only screen and (min-width:981px){ #related-wrap.hm-related-centered{ float:none; clear:both; margin-left:auto; margin-right:auto; } }
/* Load 7 related posts, but keep an even 6-card layout on mobile */ @media only screen and (max-width:680px){ .related-posts>.related-item:nth-child(7){ display:none!important; } }
/* ======================================== 게시물 하단 공유·안내 카드 - PC: 실제 추천 카드 행의 시각적 폭과 정확히 일치 - 색상: 화이트 + 블루그레이 + 단일 블루 포인트 ======================================== */ .hm-post-tools { box-sizing: border-box; margin-top: 28px; margin-bottom: 24px; overflow: hidden; background: #ffffff; border: 1px solid #dfe7f1; border-radius: 14px; box-shadow: 0 8px 24px rgba(15, 23, 42, .07); }
.hm-share-row { min-height: 66px; padding: 12px 20px; gap: 24px; background: linear-gradient(135deg, #f7fbff 0%, #ffffff 62%); }
.hm-share-copy { gap: 10px; }
.hm-share-symbol, .hm-info-icon { width: 32px; height: 32px; background: #eef5ff; border: 1px solid #dbeafe; }
.hm-share-symbol svg, .hm-info-icon svg { width: 17px; height: 17px; stroke: #2563eb; }
.hm-share-title strong { color: #1e293b; font-size: 14.5px; }
.hm-share-title span { color: #64748b; font-size: 11.5px; }
.hm-share-buttons, .hm-share-more { gap: 9px; }
.hm-btn { width: 40px; height: 40px; box-shadow: 0 2px 5px rgba(15, 23, 42, .12); }
.hm-btn svg { width: 20px; height: 20px; }
.hm-btn:hover { transform: translateY(-1px); box-shadow: 0 4px 10px rgba(15, 23, 42, .17); }
.hm-info-box { border-top: 1px solid #e6edf5; }
.hm-info-box summary { min-height: 50px; padding: 10px 20px; background: #f8fafc; transition: background-color .18s ease; }
.hm-info-box summary:hover { background: #f3f7fb; }
.hm-info-title { color: #334155; font-size: 13.5px; }
.hm-arrow svg { stroke: #94a3b8; }
.hm-info-box[open] summary { background: #f8fafc; border-bottom-color: #e6edf5; }
.hm-info-content { background: #ffffff; }
.hm-label, .hm-info-links a { color: #2563eb; }
/* 실제 추천 카드 행 폭은 JS가 --hm-related-row-width에 기록한다. */ @media only screen and (min-width:769px) { .hm-post-tools { position: relative !important; left: 50% !important; width: var(--hm-related-row-width, 100%) !important; max-width: calc(100vw - 48px) !important; margin: 26px 0 24px !important; transform: translateX(-50%) !important; } }
/* 넓은 카드에서도 펼친 안내문은 과도하게 길어지지 않게 제한 */ body.hm-webtool-page .hm-info-content { width: 100%; max-width: 1040px; margin-left: auto; margin-right: auto; padding: 6px 22px 18px; }
@media (max-width: 768px) { .hm-post-tools, body.hm-webtool-page .hm-post-tools { position: relative !important; left: auto !important; width: calc(100% - 24px) !important; max-width: none !important; margin: 24px 12px 20px !important; transform: none !important; border-radius: 12px; }
.hm-share-row { min-height: 0; padding: 14px; gap: 12px; }
.hm-share-buttons { gap: 8px; }
.hm-info-box summary { min-height: 48px; padding: 10px 14px; }
body.hm-webtool-page .hm-info-content { max-width: none; padding: 2px 14px 15px; } }
/* ========================================================= HM 게시물 하단 최종 정리 - 공유 버튼 중앙 정렬 - 공유·안내 카드 시각적 단순화 - 태그와 추천 게시물 사이 불필요한 세로 공간 제거 ========================================================= */
/* 웹도구 배경은 유지하되 게시물 컨테이너의 화면 높이 강제는 해제 */ body.hm-webtool-page .entry-content-wrap, body.hm-webtool-page #post-body { min-height: 0 !important; }
/* 공유 영역: 제목 위, 버튼 아래 중앙 정렬 */ .hm-share-row { min-height: 0; flex-direction: column; align-items: center; justify-content: center; gap: 12px; padding: 18px 20px 16px; text-align: center; background: #ffffff; }
.hm-share-copy { width: 100%; justify-content: center; gap: 9px; }
.hm-share-title { align-items: center; text-align: center; }
.hm-share-title strong { font-size: 14.5px; letter-spacing: -0.01em; }
.hm-share-title span { font-size: 11.5px; }
.hm-share-symbol { width: 30px; height: 30px; background: #f3f7fc; border-color: #e2eaf4; }
.hm-share-symbol svg { width: 16px; height: 16px; }
.hm-share-buttons { width: 100%; justify-content: center; gap: 10px; }
.hm-share-more, .hm-share-more.active { justify-content: center; }
.hm-btn { width: 39px; height: 39px; box-shadow: 0 2px 5px rgba(15, 23, 42, .10); }
.hm-btn svg { width: 19px; height: 19px; }
/* 통합 카드: 과한 그라데이션과 그림자를 줄인 중립형 디자인 */ .hm-post-tools { background: #ffffff; border-color: #e2e8f0; border-radius: 12px; box-shadow: 0 5px 18px rgba(15, 23, 42, .055); }
.hm-info-box { border-top-color: #e8edf3; }
.hm-info-box summary { min-height: 48px; padding: 10px 18px; background: #f8fafc; }
.hm-info-box summary:hover, .hm-info-box[open] summary { background: #f5f8fc; }
.hm-info-icon { width: 28px; height: 28px; background: #ffffff; border-color: #dfe7f1; }
.hm-info-icon svg { width: 15px; height: 15px; }
.hm-info-title { font-size: 13px; font-weight: 700; }
/* 태그: 한 줄짜리 보조 정보로 축소 */ .entry-content-wrap > .entry-labels, body.hm-webtool-page .entry-content-wrap > .entry-labels { float: none !important; clear: both !important; width: 100% !important; min-height: 0 !important; display: flex !important; align-items: center !important; flex-wrap: wrap !important; margin: 10px 0 12px !important; padding: 0 !important; line-height: 1.35 !important; }
.entry-content-wrap > .entry-labels > div { display: flex; align-items: center; flex-wrap: wrap; gap: 6px; }
.entry-content-wrap > .entry-labels span, .entry-content-wrap > .entry-labels a { margin: 0 !important; font-size: 12px !important; line-height: 1.35 !important; }
.entry-content-wrap > .entry-labels .labels-label { color: #64748b !important; font-weight: 600 !important; }
.entry-content-wrap > .entry-labels a { color: #f97316 !important; font-weight: 500 !important; }
.entry-content-wrap > .entry-labels a::after { content: "" !important; display: none !important; }
/* 태그 다음 추천 게시물이 바로 이어지도록 간격 축소 */ .post-footer { clear: both; }
#related-wrap { margin-top: 18px; }
@media (max-width: 768px) { .hm-share-row { align-items: center; padding: 16px 14px 14px; gap: 11px; }
.hm-share-copy { width: 100%; justify-content: center; }
.hm-share-buttons { justify-content: center; gap: 8px; }
.hm-btn { width: 38px; height: 38px; }
.entry-content-wrap > .entry-labels, body.hm-webtool-page .entry-content-wrap > .entry-labels { margin: 8px 12px 10px !important; width: calc(100% - 24px) !important; }
#related-wrap { margin-top: 14px; } }
/* ========================================================= HEALINGMART HOME 2026 - SELECTED MOCKUP / PC FIRST ========================================================= */ @media (min-width:981px){ :root{--max-width:1320px;--gap:24px} .is-home #header-wrapper{margin-bottom:0} .is-home #content-wrapper{max-width:1320px;padding:22px 24px 12px} .is-home #main-wrapper{width:calc(100% - 286px)} .is-home #sidebar-wrapper{width:262px} .is-home .blog-posts-wrap{padding:0;background:transparent;box-shadow:none;border:0} .is-home .index-post-wrap{grid-template-columns:repeat(4,minmax(0,1fr))!important;gap:14px!important} .is-home .index-post{border:1px solid #e5eaf2;border-radius:12px;overflow:hidden;background:#fff;box-shadow:0 5px 18px rgba(15,23,42,.04)} .is-home .index-post .entry-header{padding:13px 14px 15px} .is-home .index-post .entry-title,.is-home .index-post .entry-title a{font-size:15px!important;line-height:1.42!important} .is-home #sidebar-wrapper .widget{border:1px solid #e5eaf2;border-radius:12px;background:#fff;box-shadow:0 5px 18px rgba(15,23,42,.04)} }
#hero-wrapper{padding:0!important;margin:0!important;background:#f7faff} #hero-wrapper>.container.row-x1,#hero-post{max-width:100%!important;width:100%!important} #hero-post{display:block!important} #hero-post>.widget{margin:0!important} #hero-post>.widget>.widget-content{padding:0!important}
.hm26{--blue:#2563eb;--blue2:#0b5cff;--ink:#111827;--muted:#64748b;--line:#e4eaf3;--surface:#fff;--soft:#f5f8ff;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","Noto Sans KR",Arial,sans-serif;color:var(--ink);background:#fff} .hm26 *{box-sizing:border-box} .hm26 a{text-decoration:none} .hm26-shell{width:min(1320px,calc(100% - 48px));margin:0 auto} .hm26-hero{position:relative;overflow:hidden;background:radial-gradient(circle at 78% 25%,#fff 0 9%,transparent 30%),linear-gradient(105deg,#f8fbff 0%,#edf4ff 58%,#e9f1ff 100%);border-bottom:1px solid #e7edf7} .hm26-hero-inner{min-height:330px;display:grid;grid-template-columns:minmax(0,1.08fr) minmax(420px,.92fr);align-items:center;gap:34px;padding:34px 0 28px} .hm26-eyebrow{display:inline-flex;align-items:center;gap:7px;height:28px;padding:0 12px;border:1px solid #bfd3ff;border-radius:999px;background:rgba(255,255,255,.78);color:#1663e8;font-size:12px;font-weight:800} .hm26-title{font-size:43px;line-height:1.17;letter-spacing:-1.7px;margin:13px 0 8px;font-weight:850;color:#111827} .hm26-title strong{display:block;color:#1764e8} .hm26-desc{font-size:15px;color:#5f6b7d;line-height:1.65;margin:0 0 17px} .hm26-search{display:flex;width:min(100%,690px);height:52px;background:#fff;border:2px solid #2b6df1;border-radius:10px;overflow:hidden;box-shadow:0 8px 22px rgba(37,99,235,.1)} .hm26-search input{min-width:0;flex:1;border:0;background:#fff;padding:0 17px;font-size:14px;color:#111827} .hm26-search button{width:103px;border:0;background:linear-gradient(135deg,#1764e8,#0b55dc);color:#fff;font-size:15px;font-weight:750;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:7px} .hm26-chips{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-top:11px} .hm26-chip{height:30px;display:inline-flex;align-items:center;padding:0 13px;border:1px solid #dae3f1;border-radius:999px;background:rgba(255,255,255,.86);font-size:12px;font-weight:650;color:#3d4a5d} .hm26-chip.hot{color:#1764e8;font-weight:800} .hm26-art{position:relative;height:280px;display:flex;align-items:center;justify-content:center} .hm26-orbit{position:absolute;width:385px;height:228px;border-radius:50%;background:radial-gradient(circle,#fff 0 30%,rgba(255,255,255,.35) 66%,transparent 67%);filter:drop-shadow(0 25px 30px rgba(65,105,190,.08))} .hm26-art-card{position:absolute;display:flex;align-items:center;justify-content:center;background:linear-gradient(145deg,#fff,#e8f0ff);border:1px solid rgba(255,255,255,.9);box-shadow:0 18px 30px rgba(72,111,190,.15),inset 0 1px 1px #fff;color:#1f67e8;border-radius:19px} .hm26-art-card svg{width:46%;height:46%} .hm26-calc{width:135px;height:177px;right:112px;top:38px;display:block;padding:18px 14px} .hm26-calc-screen{height:33px;border-radius:8px;background:#dce8ff;color:#374151;font-size:17px;font-weight:800;display:flex;align-items:center;justify-content:flex-end;padding:0 10px;margin-bottom:12px} .hm26-keys{display:grid;grid-template-columns:repeat(3,1fr);gap:7px}.hm26-keys i{height:22px;border-radius:6px;background:linear-gradient(#72a4ff,#2f6eea);box-shadow:inset 0 1px 1px rgba(255,255,255,.8)} .hm26-weather{width:92px;height:92px;right:255px;top:56px;color:#f59e0b} .hm26-calendar{width:84px;height:84px;right:300px;bottom:36px} .hm26-image{width:104px;height:78px;right:184px;bottom:15px} .hm26-swap{width:85px;height:85px;right:60px;bottom:36px} .hm26-magnify{position:absolute;width:110px;height:110px;border:17px solid #3274ec;border-radius:50%;right:14px;bottom:6px;background:rgba(255,255,255,.35);box-shadow:0 17px 30px rgba(30,91,210,.18)} .hm26-magnify:after{content:'';position:absolute;width:66px;height:19px;background:linear-gradient(90deg,#3677ed,#1657d8);border-radius:12px;right:-53px;bottom:-27px;transform:rotate(45deg);box-shadow:0 10px 20px rgba(30,91,210,.18)}
