/* Never translate the share/info card from an inferred related-card width. */ @media only screen and (min-width:769px){ .hm-post-tools, body.hm-webtool-page .hm-post-tools{ position:relative!important; left:auto!important; float:none!important; clear:both!important; width:calc(100% - 40px)!important; max-width:1200px!important; margin:26px auto 24px!important; transform:none!important; } }
/* Keep related posts and comments on the same centered axis on normal and service posts. HealingMart width policy: related posts + comments = max 1320px. */ body.is-single #related-wrap, body.is-single .vtrick-pro-blog-post-comments{ position:relative!important; left:auto!important; float:none!important; clear:both!important; width:100%!important; max-width:1320px!important; margin-left:auto!important; margin-right:auto!important; transform:none!important; box-sizing:border-box!important; } body.is-single #related-wrap .related-posts{ width:100%!important; grid-template-columns:repeat(auto-fit,minmax(180px,1fr))!important; } body.is-single .vtrick-pro-blog-post-comments #comments, body.is-single .vtrick-pro-blog-post-comments .comments, body.is-single .vtrick-pro-blog-post-comments .comment-form, body.is-single .vtrick-pro-blog-post-comments iframe{ width:100%!important; max-width:100%!important; margin-left:auto!important; margin-right:auto!important; box-sizing:border-box!important; } @media only screen and (max-width:768px){ .hm26-hub-switcher{height:52px;margin-top:18px} .hm26-hub-switcher>a{gap:5px;padding:0 4px;font-size:12px} .hm26-hub-switcher>a i{font-size:15px} body.is-single #related-wrap .related-posts{grid-template-columns:repeat(2,minmax(0,1fr))!important} }
/* ========================================================= HealingMart v20.4.3 — mobile post horizontal spacing fix Removes the VTrick nested 3rem + 2rem mobile padding stack. ========================================================= */ @media only screen and (max-width:680px){ body.is-post #content-wrapper, body.is-page #content-wrapper{ width:100%!important; max-width:none!important; padding:10px 8px calc(94px + env(safe-area-inset-bottom))!important; overflow:visible!important; } body.is-post #content-wrapper>.container, body.is-page #content-wrapper>.container, body.is-post #main-wrapper, body.is-page #main-wrapper{ width:100%!important; max-width:100%!important; padding-left:0!important; padding-right:0!important; } body.is-post .item-post-wrap, body.is-page .item-post-wrap, body.is-post .item-post-inner, body.is-page .item-post-inner{ width:100%!important; max-width:100%!important; padding-left:0!important; padding-right:0!important; } body.is-post .entry-content-wrap, body.is-page .entry-content-wrap{ width:100%!important; max-width:100%!important; margin-top:8px!important; padding:16px 14px 8px!important; border-radius:16px!important; box-sizing:border-box!important; } body.is-post #related-wrap, body.is-page #related-wrap, body.is-post .vtrick-pro-blog-post-comments, body.is-page .vtrick-pro-blog-post-comments{ width:100%!important; max-width:100%!important; padding-left:0!important; padding-right:0!important; box-sizing:border-box!important; } body.hm-life-info-hub .entry-content-wrap{ margin-top:0!important; padding:0!important; border-radius:0!important; background:transparent!important; box-shadow:none!important; } }

