(function(){
    var kakaoPromise = null;
    function loadKakao() {
        if (window.Kakao) {
            if (!window.Kakao.isInitialized()) window.Kakao.init('a6897bdb5b7785b0ffbe542d81886b93');
            return Promise.resolve(window.Kakao);
        }
        if (kakaoPromise) return kakaoPromise;
        kakaoPromise = new Promise(function(resolve, reject) {
            var script = document.createElement('script');
            script.src = 'https://developers.kakao.com/sdk/js/kakao.min.js';
            script.async = true;
            script.onload = function() {
                try {
                    if (!window.Kakao.isInitialized()) window.Kakao.init('a6897bdb5b7785b0ffbe542d81886b93');
                    resolve(window.Kakao);
                } catch (error) { reject(error); }
            };
            script.onerror = reject;
            document.head.appendChild(script);
        }).catch(function(error) { kakaoPromise = null; throw error; });
        return kakaoPromise;
    }
    function getShareData() {
        return {
            url: window.location.href,
            title: document.title,
            desc: document.querySelector('meta[name="description"]') ? document.querySelector('meta[name="description"]').content : '힐링마트의 유용한 정보를 확인해보세요!',
            img: document.querySelector('meta[property="og:image"]') ? document.querySelector('meta[property="og:image"]').content : ''
        };
    }
    window.hmToggleMore = function() { document.querySelector('.hm-share-more').classList.toggle('active'); };
    window.hmShareKakao = function() {
        var d = getShareData();
        loadKakao().then(function(Kakao) {
            Kakao.Share.sendDefault({
                objectType: 'feed',
                content: { title: d.title, description: d.desc, imageUrl: d.img, link: { mobileWebUrl: d.url, webUrl: d.url } }
            });
        }).catch(function() {
            window.open('https://story.kakao.com/share?url=' + encodeURIComponent(d.url), '_blank', 'noopener,noreferrer');
        });
    };
    window.hmShareNaver = function() {
        var d = getShareData();
        window.open('https://share.naver.com/web/shareView?url=' + encodeURIComponent(d.url) + '&title=' + encodeURIComponent(d.title), '_blank');
    };
    window.hmShareFacebook = function() {
        var d = getShareData();
        window.open('https://www.facebook.com/sharer/sharer.php?u=' + encodeURIComponent(d.url), '_blank');
    };
    window.hmShareX = function() {
        var d = getShareData();
        window.open('https://twitter.com/intent/tweet?url=' + encodeURIComponent(d.url) + '&text=' + encodeURIComponent(d.title), '_blank');
    };
    window.hmShareThreads = function() {
        var d = getShareData();
        window.open('https://www.threads.net/intent/post?text=' + encodeURIComponent(d.title + '\n' + d.url), '_blank');
    };
    window.hmShareBand = function() {
        var d = getShareData();
        window.open('https://band.us/plugin/share?body=' + encodeURIComponent(d.title + '\r\n' + d.url), '_blank');
    };
    window.hmShareTelegram = function() {
        var d = getShareData();
        window.open('https://t.me/share/url?url=' + encodeURIComponent(d.url) + '&text=' + encodeURIComponent(d.title), '_blank');
    };
    window.hmShareCopy = function() {
        var d = getShareData();
        navigator.clipboard.writeText(d.url).then(() => alert('링크가 복사되었습니다!'));
    };
})();
