(function(){
    function applyHmWebtoolMode(){
        var postBody = document.getElementById('post-body');
        if (!postBody) return;

        var mapMarker = postBody.querySelector(
            '[data-hm-map-page], .hm-map-page, .hm-map-service, [data-hm-fullscreen], .hm-fullscreen-tool'
        );
        if (mapMarker) {
            document.body.classList.remove('hm-webtool-page');
            document.body.classList.add('hm-map-page', 'hm-fullscreen-page', 'hm-no-sidebar', 'hm-service-view');
            return;
        }

        var marker = postBody.querySelector(
            '[data-hm-webtool], .hm-webtool, .healingmart-webtool, .webtool-app, .tool-app, .tool-shell, .app-shell, ' +
            '#hm-webtool, #webtool-app, #tool-app, #healingMartTextCounter, #healingMartCalculator, #healingMartCalculatorApp, [data-hm-calc-app], ' +
            '#healingMartConverter, #hmxrnApp, [data-hmxrn-tool-root], #hmMiniGameHubPost, .hm-tool-shell, .hm-game-page'
        );
        /* 일반 게시물의 버튼 개수나 높이로 도구 페이지를 추측하지 않는다. */
        if (marker) {
            document.body.classList.remove('hm-map-page', 'hm-fullscreen-page');
            document.body.classList.add('hm-webtool-page', 'hm-no-sidebar', 'hm-service-view');
        }
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', applyHmWebtoolMode);
    } else {
        applyHmWebtoolMode();
    }

    window.addEventListener('load', applyHmWebtoolMode);
    window.setTimeout(applyHmWebtoolMode, 800);
})();
