b:if.script:
//
document.addEventListener('DOMContentLoaded', function(){
  var postBody = document.getElementById('post-body');
  if (!postBody) return;

  var headings = postBody.querySelectorAll('h2, h3, h4');
  if (headings.length < 2) return;

  function extractCleanText(heading) {
    var clone = heading.cloneNode(true);
    clone.querySelectorAll('span.bg-primary, span[class*="rounded-full"], span[class*="badge"]').forEach(function(el){
      el.remove();
    });
    return clone.textContent.trim().replace(/\s+/g, ' ');
  }

  function generateId(text, index) {
    var id = text.toLowerCase()
                 .replace(/[^a-z0-9가-힣 ]/g, '')
                 .replace(/\s+/g, '-')
                 .substring(0, 50);
    return id ? 'hm-h-' + id : 'hm-h-' + index;
  }

  headings.forEach(function(h, i){
    if (!h.id) h.id = generateId(extractCleanText(h), i);
  });

  var tocList = document.createElement('ul');
  tocList.className = 'hm-toc-list';

  var h2Count = 0;
  var totalCount = 0;

  headings.forEach(function(h){
    var level = parseInt(h.tagName.substring(1));
    var text = extractCleanText(h);
    if (!text) return;

    totalCount++;

    var li = document.createElement('li');
    li.className = 'hm-toc-item hm-toc-h' + level;

    if (level === 2) {
      h2Count++;
      var num = document.createElement('span');
      num.className = 'hm-toc-num';
      num.textContent = h2Count.toString().padStart(2, '0');
      li.appendChild(num);
    }

    var a = document.createElement('a');
    a.href = '#' + h.id;
    a.className = 'hm-toc-link';
    a.textContent = text;
    li.appendChild(a);

    tocList.appendChild(li);
  });

  var wrap = document.createElement('div');
  wrap.className = 'hm-toc-wrap';
  wrap.innerHTML = 
    '<button type="button" class="hm-toc-header" aria-expanded="false">' +
      '<div class="hm-toc-icon">' +
        '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">' +
          '<line x1="4" y1="7" x2="20" y2="7"></line>' +
          '<line x1="4" y1="12" x2="20" y2="12"></line>' +
          '<line x1="4" y1="17" x2="14" y2="17"></line>' +
        '</svg>' +
      '</div>' +
      '<div class="hm-toc-title">' +
        '<strong>목차</strong>' +
        '<span class="hm-toc-count">' + totalCount + '개 항목</span>' +
      '</div>' +
      '<div class="hm-toc-toggle">' +
        '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">' +
          '<polyline points="6 9 12 15 18 9"></polyline>' +
        '</svg>' +
      '</div>' +
    '</button>' +
    '<div class="hm-toc-body"></div>';

  wrap.querySelector('.hm-toc-body').appendChild(tocList);
  headings[0].parentNode.insertBefore(wrap, headings[0]);

  var header = wrap.querySelector('.hm-toc-header');
  var body = wrap.querySelector('.hm-toc-body');
  header.addEventListener('click', function(){
    var isOpen = wrap.classList.contains('is-open');
    if (isOpen) {
      body.style.maxHeight = '0';
      wrap.classList.remove('is-open');
      header.setAttribute('aria-expanded', 'false');
    } else {
      body.style.maxHeight = body.scrollHeight + 'px';
      wrap.classList.add('is-open');
      header.setAttribute('aria-expanded', 'true');
    }
  });

  wrap.querySelectorAll('a').forEach(function(a){
    a.addEventListener('click', function(e){
      e.preventDefault();
      var target = document.querySelector(a.getAttribute('href'));
      if (target) {
        var top = target.getBoundingClientRect().top + window.pageYOffset - 70;
        window.scrollTo({top: top, behavior: 'smooth'});
      }
    });
  });
});
