(function(window,document){
  "use strict";
  if(window.HM_HOME_POST_BATCH_LOADER)return;
  window.HM_HOME_POST_BATCH_LOADER=true;

  var busy=false;
  var maxPagesPerAction=6;

  function q(selector,root){return (root||document).querySelector(selector);}
  function qa(selector,root){return Array.prototype.slice.call((root||document).querySelectorAll(selector));}
  function isHome(){return document.body&&document.body.classList.contains("is-home");}
  function grid(){return q(".is-home .blog-posts.index-post-wrap");}
  function pagerButton(){return q("#vtrick-pro-load-more-link");}
  function loadingNode(){return q("#blog-pager .loading");}
  function noMoreNode(){return q("#blog-pager .no-more");}
  function canonical(value){
    try{var u=new URL(String(value||""),location.href);u.hash="";u.search="";return u.href.replace(/\/$/,"");}
    catch(error){return String(value||"").replace(/[?#].*$/,"").replace(/\/$/,"");}
  }
  function cardKey(card){
    var a=q(".entry-title a[href],a.entry-image-wrap[href]",card);
    return canonical(a&&a.href||"");
  }
  function visibleColumns(target){
    if(!target)return 4;
    try{
      var value=getComputedStyle(target).gridTemplateColumns||"";
      var cols=value.split(/\s+/).filter(Boolean).length;
      return Math.max(1,cols||1);
    }catch(error){return 4;}
  }
  function actionTarget(target){
    return Math.max(4,visibleColumns(target));
  }
  function setBusy(state){
    busy=state;
    var btn=pagerButton(),loader=loadingNode();
    if(btn){btn.setAttribute("aria-busy",state?"true":"false");btn.style.display=state?"none":"";}
    if(loader)loader.style.display=state?"":"none";
  }
  function finishPager(nextUrl){
    var btn=pagerButton(),noMore=noMoreNode();
    if(nextUrl){
      if(btn){btn.dataset.load=nextUrl;btn.style.display="";btn.removeAttribute("hidden");}
      if(noMore)noMore.classList.remove("show");
    }else{
      if(btn)btn.style.display="none";
      if(noMore)noMore.classList.add("show");
    }
  }
  function highResThumbUrl(value){
    return String(value||"")
      .replace(/\/w\d+-h\d+(?:-[^/]+)?\//i,"/s1200/")
      .replace(/\/s\d+(?:-c)?\//i,"/s1200/")
      .replace(/=w\d+-h\d+(?:-[^&]+)?(?:&|$)/i,"=s1200$1")
      .replace(/=s\d+(?:-c)?(?:&|$)/i,"=s1200$1");
  }
  function refreshImages(nodes){
    try{
      var jq=window.jQuery;
      var roots=jq?jq(nodes):null;
      if(roots){
        roots.find(".entry-image-wrap .entry-thumb[data-image]").each(function(){
          var el=this,src=highResThumbUrl(el.getAttribute("data-image"));
          if(src)el.setAttribute("data-image",src);
        });
      }
      if(jq&&jq.fn&&typeof jq.fn.lazyify==="function"){
        roots.find(".entry-image-wrap .entry-thumb,.author-avatar-wrap .author-avatar").lazyify();
      }
    }catch(error){}
  }
  function fetchPage(url){
    return fetch(url,{credentials:"same-origin",cache:"no-store",headers:{Accept:"text/html"}}).then(function(response){
      if(!response.ok)throw new Error("load_more_http_"+response.status);
      return response.text();
    }).then(function(html){
      var doc=new DOMParser().parseFromString(html,"text/html");
      var cards=qa(".blog-posts.index-post-wrap .index-post",doc);
      var next=q("#vtrick-pro-load-more-link",doc);
      return {cards:cards,nextUrl:next&&next.getAttribute("data-load")||""};
    });
  }
  function loadBatch(options){
    options=options||{};
    if(busy||!isHome())return Promise.resolve(0);
    var target=grid(),btn=pagerButton();
    if(!target||!btn)return Promise.resolve(0);
    var nextUrl=btn.getAttribute("data-load")||btn.dataset.load||"";
    if(!nextUrl){finishPager("");return Promise.resolve(0);}

    var wanted=Math.max(1,Number(options.wanted)||actionTarget(target));
    var appended=0,pages=0,seen={};
    qa(".index-post",target).forEach(function(card){var key=cardKey(card);if(key)seen[key]=true;});
    setBusy(true);

    function next(){
      if(!nextUrl||appended>=wanted||pages>=maxPagesPerAction)return Promise.resolve();
      var current=nextUrl;pages++;
      return fetchPage(current).then(function(result){
        nextUrl=result.nextUrl||"";
        var added=[];
        result.cards.forEach(function(card){
          var key=cardKey(card);
          if(key&&seen[key])return;
          if(key)seen[key]=true;
          card.classList.add("post-animated","post-fadeInUp");
          target.appendChild(card);
          added.push(card);appended++;
        });
        if(added.length)refreshImages(added);
        if(nextUrl&&appended<wanted)return next();
      });
    }

    return next().catch(function(error){
      console.warn("HealingMart home load more",error);
    }).then(function(){
      setBusy(false);finishPager(nextUrl);return appended;
    });
  }

  document.addEventListener("click",function(event){
    var btn=event.target&&event.target.closest&&event.target.closest("#vtrick-pro-load-more-link");
    if(!btn||!isHome())return;
    event.preventDefault();
    event.stopPropagation();
    if(event.stopImmediatePropagation)event.stopImmediatePropagation();
    loadBatch();
  },true);

  function install(){
    if(!isHome())return;
    var btn=pagerButton();
    if(!btn)return;
    try{if(window.jQuery)window.jQuery(btn).off("click");}catch(error){}
    /* Blogger automatic pagination can make the first response unusually short.
       Only top up when the initial grid is visibly sparse; otherwise do not auto-load. */
    var target=grid();
    if(target){
      var columns=visibleColumns(target);
      var minimum=Math.max(columns,4);
      var current=qa(".index-post",target).length;
      if(current<minimum)loadBatch({wanted:minimum-current});
    }
  }
  if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",function(){setTimeout(install,0);});
  else setTimeout(install,0);
})(window,document);
