  function node(tag,className,text){var item=document.createElement(tag);if(className)item.className=className;if(typeof text==="string")item.textContent=text;return item;}
  function normalizeKnownHubLink(link){
    if(!link||!link.getAttribute)return;
    var raw=link.getAttribute("href")||"",url;
    if(!raw||raw.charAt(0)==="#"||/^javascript:|^mailto:|^tel:/i.test(raw))return;
    try{
      url=new URL(raw,window.location.href);
      var host=url.hostname.toLowerCase().replace(/^www\./,"");
      if(host!=="healing-mart.com")return;
      if(String(url.pathname||"").toLowerCase()!=="/2026/07/webtools.html")return;
      if(url.pathname==="/2026/07/Webtools.html")return;
      url.pathname="/2026/07/Webtools.html";
      link.setAttribute("href",url.toString());
    }catch(error){}
  }
  function installKnownHubLinkFix(){
