  function clean(value){return String(value||"").replace(/\s+/g," ").trim();}
  function normalized(value){var text=clean(value).toLowerCase();if(text.normalize)text=text.normalize("NFKC");return text.replace(/[^0-9a-z가-힣]+/g," ").replace(/\s+/g," ").trim();}
  function blocked(item){
    var blockedDomain="tistory"+"100.com";
    try{var host=new URL(item&&item.url||"",window.location.href).hostname.toLowerCase();if(host===blockedDomain||host.slice(-(blockedDomain.length+1))==="."+blockedDomain)return true;}catch(error){}
    return false;
