    var explicit=String(item&&item.bloggerType||item&&item.catalogType||"").toLowerCase();
    if(/webservice|web-service|web service/.test(explicit))return "webservice";
    var value=String(item&&item.toolType||item&&item.resultType||item&&item.subtype||item&&item.type||"").toLowerCase();
    if(/calculator/.test(value))return "calculator";
