  function normalizedUrlKey(value){
    try{
      var url=new URL(String(value||""),window.location.href),host=url.hostname.toLowerCase().replace(/^www\./,"");
      url.hash="";
      ["m","utm_source","utm_medium","utm_campaign","utm_term","utm_content","fbclid","gclid","dclid","mc_cid","mc_eid","ref","source"].forEach(function(name){
        if(name==="m"&&url.searchParams.get(name)!=="1")return;
        url.searchParams.delete(name);
      });
      var pairs=[];url.searchParams.forEach(function(v,k){pairs.push([k,v]);});pairs.sort(function(a,b){return a[0].localeCompare(b[0])||a[1].localeCompare(b[1]);});
      var query=pairs.map(function(row){return encodeURIComponent(row[0])+"="+encodeURIComponent(row[1]);}).join("&");
      var path=(url.pathname||"/").replace(/\/{2,}/g,"/");if(path.length>1)path=path.replace(/\/+$/,"");
      return host+path+(query?"?"+query:"");
    }catch(error){return String(value||"").replace(/#.*$/,"").replace(/\/?(?:\?m=1)?$/,"");}
  }
  function canonicalUrl(value){
    try{var url=new URL(String(value||""),window.location.href);url.hash="";if(url.searchParams.get("m")==="1")url.searchParams.delete("m");return url.origin+url.pathname.replace(/\/$/,"")+(url.searchParams.toString()?"?"+url.searchParams.toString():"");}
    catch(error){return String(value||"").replace(/#.*$/,"");}
  }
  function dedupe(items){
    var seen={};
    return (items||[]).filter(function(item){
      if(!item||!item.url||!(item.title||item.name)||blocked(item))return false;
      var key=String(item.id||"")+"|"+canonicalUrl(item.url);
      if(seen[key])return false;
      seen[key]=true;
      return true;
    });
  }
  function grouped(payload){
    payload=payload||{};
