    var toolSeen={},gameSeen={},serviceSeen={};
    tools.forEach(function(item){toolSeen[String(item.id||"")+"|"+canonicalUrl(item.url)]=true;});
    games.forEach(function(item){gameSeen[String(item.id||"")+"|"+canonicalUrl(item.url)]=true;});
    dedupe(payload.services||[]).forEach(function(item){
      var key=String(item.id||"")+"|"+canonicalUrl(item.url),type=resultType(item);
      if(["calculator","converter","webtool"].indexOf(type)>=0){if(!toolSeen[key]){toolSeen[key]=true;tools.push(item);}return;}
      if(type==="game"){if(!gameSeen[key]){gameSeen[key]=true;games.push(item);}return;}
      if(!serviceSeen[key]){serviceSeen[key]=true;services.push(item);}
    });
