    if(self.mode==="converter")tools=tools.filter(function(item){return resultType(item)==="converter";});
    if(self.mode==="webtool")tools=tools.filter(function(item){return resultType(item)==="webtool";});
    self.results.replaceChildren();
    var shown=0;
    if(self.mode==="all"){
      shown+=appendGroup(self.results,"계산기 · 컨버터 · 웹도구",tools,self.categoryMap);
      shown+=appendGroup(self.results,"미니게임",g.games,self.categoryMap);
      shown+=appendGroup(self.results,"생활 서비스",g.services,self.categoryMap);
      shown+=appendGroup(self.results,"블로그 게시물",g.posts,self.categoryMap);
    }else if(["tools","calculator","converter","webtool"].indexOf(self.mode)>=0){
      shown+=appendGroup(self.results,self.mode==="calculator"?"계산기":self.mode==="converter"?"컨버터":self.mode==="webtool"?"웹도구":"전체 웹도구",tools,self.categoryMap);
    }else if(self.mode==="games")shown+=appendGroup(self.results,"미니게임",g.games,self.categoryMap);
    else if(self.mode==="services")shown+=appendGroup(self.results,"생활 서비스",g.services,self.categoryMap);
    else if(self.mode==="posts")shown+=appendGroup(self.results,"블로그 게시물",g.posts,self.categoryMap);
    if(!shown)empty(self.results,"선택한 범위에 결과가 없습니다.");
    if(self.meta){
      if(self.mode==="all"){
        if(self.query)self.meta.textContent="전체 "+g.total+"개 · 도구 "+tools.length+" · 게임 "+g.games.length+" · 생활서비스 "+g.services.length+" · 게시물 "+g.posts.length;
        else self.meta.textContent="전체 "+g.total+"개 · 도구 "+tools.length+" · 게임 "+g.games.length;
      }else self.meta.textContent=(self.query?"검색어: "+self.query+" · ":"")+shown+"개";
    }
    if(self.categoriesBox)self.categoriesBox.hidden=["all","tools","calculator","converter","webtool"].indexOf(self.mode)<0;
    self.renderTabs();
    self.selectCategory();
  };
  SearchView.prototype.search=function(value){
    var self=this,id=self.beginRequest();
    self.prepare();
    self.query=clean(typeof value==="string"?value:self.input.value);
    if(typeof value==="string")self.input.value=self.query;
    self.category="";
    self.mode="all";
    if(!self.query){self.panel.hidden=true;self.results.replaceChildren();return Promise.resolve();}
    self.panel.hidden=false;
    loading(self.results);
    if(self.meta)self.meta.textContent="검색 중";
    return searchUnified(self.query).then(function(payload){
      if(!self.isCurrent(id))return;
      self.payload=payload||{};
      self.render();
    }).catch(function(){
      if(!self.isCurrent(id))return;
      empty(self.results,"통합검색을 불러오지 못했습니다. 서비스 플랫폼 배포 상태를 확인하세요.");
      if(self.meta)self.meta.textContent="연결 실패";
    });
  };
  SearchView.prototype.openGames=function(){
    var self=this,id=self.beginRequest();
    self.query="";
    self.input.value="";
    self.category="";
    self.mode="games";
    self.panel.hidden=false;
    loading(self.results);
    if(self.meta)self.meta.textContent="게임 목록 불러오는 중";
    return self.loadGames().then(function(items){
      if(!self.isCurrent(id))return;
      self.payload={games:items};
      self.render();
    }).catch(function(){if(self.isCurrent(id))empty(self.results,"게임 카탈로그를 불러오지 못했습니다.");});
  };
  SearchView.prototype.openToolsCategory=function(category){
    var self=this,id=self.beginRequest();
    self.query="";
    self.input.value="";
    self.category=category;
    self.mode="tools";
    self.panel.hidden=false;
    loading(self.results);
    return self.loadTools("",category).then(function(items){
      if(!self.isCurrent(id))return;
      self.payload={webtools:items};
      self.render();
    }).catch(function(){if(self.isCurrent(id))empty(self.results,"웹도구 카탈로그를 불러오지 못했습니다.");});
  };
  SearchView.prototype.setMode=function(mode){
    var self=this;
    if(mode==="games")return self.openGames();
    self.mode=mode;
    self.category="";
    if(!self.query&&mode==="all"){
      var allId=self.beginRequest();
      self.panel.hidden=false;loading(self.results);
      if(self.meta)self.meta.textContent="전체 카탈로그 불러오는 중";
      return Promise.all([self.loadTools("",""),self.loadGames()]).then(function(parts){
        if(!self.isCurrent(allId))return;
        self.payload={webtools:parts[0],games:parts[1]};self.render();
      }).catch(function(){if(self.isCurrent(allId))empty(self.results,"전체 카탈로그를 불러오지 못했습니다.");});
    }
    if(["tools","calculator","converter","webtool"].indexOf(mode)>=0&&!self.query){
      var id=self.beginRequest();
      self.panel.hidden=false;loading(self.results);
      return self.loadTools(mode==="tools"?"":mode,"").then(function(items){
        if(!self.isCurrent(id))return;
        self.payload={webtools:items};self.render();
      }).catch(function(){if(self.isCurrent(id))empty(self.results,"웹도구 카탈로그를 불러오지 못했습니다.");});
    }
    if(!self.query)self.beginRequest();
    self.render();
    return Promise.resolve();
  };
  SearchView.prototype.bind=function(){
    var self=this;
    if(self.tabs)self.tabs.addEventListener("click",function(event){
      var button=event.target.closest("button[data-hm-search-tab]");
      if(button)self.setMode(button.getAttribute("data-hm-search-tab")||"all");
    });
  };

  function buildFilters(parent){
    var tabs=node("div","hm28-search-tabs");
    tabs.setAttribute("data-hm-search-tabs","");
    [["all","전체"],["tools","웹도구 전체"],["calculator","계산기"],["converter","컨버터"],["webtool","웹도구"],["games","게임"],["posts","게시물"]].forEach(function(row){
      var button=node("button",row[0]==="all"?"is-active":"",row[1]);
