      tabs.appendChild(button);
    });
    var categories=node("div","hm28-search-categories");
    categories.setAttribute("data-hm-search-categories","");
    parent.append(tabs,categories);
    return {tabs:tabs,categories:categories};
  }
  var HM_UI_LAYER_KEY="hmUiLayer";
