  }
  var HM_SEARCH_HISTORY_KEY="healingmart_search_history_v1",HM_SEARCH_HISTORY_LIMIT=10;
  function readSearchHistory(){try{var rows=JSON.parse(localStorage.getItem(HM_SEARCH_HISTORY_KEY)||"[]");if(!Array.isArray(rows))return [];var seen={};return rows.map(function(raw){var value=clean(typeof raw==="string"?raw:raw&&raw.query||"").slice(0,80),time=Number(raw&&raw.time)||0,key=value.toLowerCase();return{query:value,time:time,key:key};}).filter(function(row){if(!row.query||seen[row.key])return false;seen[row.key]=true;return true;}).sort(function(a,b){return b.time-a.time;}).slice(0,HM_SEARCH_HISTORY_LIMIT);}catch(error){return [];}}
  function writeSearchHistory(rows){try{localStorage.setItem(HM_SEARCH_HISTORY_KEY,JSON.stringify((rows||[]).slice(0,HM_SEARCH_HISTORY_LIMIT).map(function(row){return{query:clean(row.query||"").slice(0,80),time:Number(row.time)||Date.now()};})));}catch(error){}}
  function renderSearchHistory(){var rows=readSearchHistory();qa("[data-hm-search-history]").forEach(function(root){root.replaceChildren();root.hidden=!rows.length||root.dataset.hmSearchHistorySuppressed==="1";if(!rows.length)return;var head=node("div","hm-search-history-head"),title=node("strong","","최근 검색"),clear=node("button","","전체 삭제");clear.type="button";clear.setAttribute("data-hm-clear-search-history","");head.append(title,clear);var chips=node("div","hm-search-history-chips");rows.forEach(function(row){var button=node("button","",row.query);button.type="button";button.title=row.query;button.setAttribute("data-hm-search-history-query",row.query);chips.appendChild(button);});root.append(head,chips);});}
  function setSearchHistoryVisible(root,visible){if(!root)return;root.dataset.hmSearchHistorySuppressed=visible?"0":"1";root.hidden=!visible||!readSearchHistory().length;}
  function recordSearchQuery(value){var query=clean(value).slice(0,80);if(!query)return;var key=query.toLowerCase(),rows=readSearchHistory().filter(function(row){return row.key!==key;});rows.unshift({query:query,time:Date.now(),key:key});writeSearchHistory(rows);renderSearchHistory();}
  function clearSearchHistory(){try{localStorage.removeItem(HM_SEARCH_HISTORY_KEY);}catch(error){}renderSearchHistory();}
  function buildSearchHistoryBox(){var root=node("div","hm-search-history");root.setAttribute("data-hm-search-history","");root.hidden=true;return root;}
