        document.documentElement.classList.add("hm-unified-search-page");
        if(document.body)document.body.classList.add("hm-unified-search-page");
        if(!q("#hm-unified-search-page-style")){
          var style=node("style","");style.id="hm-unified-search-page-style";
          style.textContent="html.hm-unified-search-page #content-wrapper{display:none!important}";
          document.head.appendChild(style);
        }
      }
      if(homeSearch&&q("[data-hm-home]"))homeSearch.run(value);else overlay.hmOpen(value);
    }catch(error){}
  }
  function classifyPageLayout(){
    var body=document.body;if(!body)return;
    var path=decodeURIComponent(location.pathname||"").replace(/\/+$/,"").toLowerCase();
    if(body.classList.contains("is-home"))body.classList.add("hm-no-sidebar");
    if(path==="/2026/08/life-info.html")body.classList.add("hm-life-info-hub");
    if(/^\/search\/label\//.test(path))body.classList.add("hm-label-page","hm-no-sidebar");
    if(!body.classList.contains("is-post")&&!body.classList.contains("is-page"))return;
    var mapMarker=q("[data-hm-map-page],.hm-map-page,.hm-map-service,[data-hm-fullscreen],.hm-fullscreen-tool");
    var webtoolMarker=q("[data-hm-webtool],#hmMiniGameHubPost,#healingMartTextCounter,#healingMartCalculator,#healingMartCalculatorApp,[data-hm-calc-app],#healingMartConverter,#hmxrnApp,[data-hmxrn-tool-root],.hm-webtool,.healingmart-webtool,.webtool-app,.tool-app,.tool-shell,.app-shell,.hm-game-page,.hm-tool-shell");
    var serviceMarker=q("[data-hm-service-page]");
    var exactHub=/^\/2026\/07\/(?:calculator|converter|webtools|free mini-games)\.html$/.test(path)||path==="/2026/08/life-info.html";
    if(mapMarker){
      body.classList.remove("hm-webtool-page");
      body.classList.add("hm-map-page","hm-fullscreen-page","hm-no-sidebar","hm-service-view");
    }else if(webtoolMarker||serviceMarker){
      body.classList.remove("hm-map-page","hm-fullscreen-page");
      body.classList.add("hm-webtool-page","hm-no-sidebar","hm-service-view");
    }else if(exactHub){
      body.classList.add("hm-no-sidebar","hm-service-view");
    }
  }
  function installBackFallback(){
    if(document.body.classList.contains("is-home")||location.pathname==="/")return;
    var standalone=window.matchMedia&&window.matchMedia("(display-mode: standalone)").matches;if(history.length>1&&!(standalone&&!document.referrer))return;
    var base={},current=history.state||{};Object.keys(current).forEach(function(key){base[key]=current[key];});base.hmBackFallbackBase=true;
    try{history.replaceState(base,"",location.href);var guard={};Object.keys(base).forEach(function(key){guard[key]=base[key];});guard.hmBackFallbackGuard=true;history.pushState(guard,"",location.href);}catch(error){return;}
    window.addEventListener("popstate",function(event){if(activeUiLayer())return;if(event.state&&event.state.hmBackFallbackBase)window.location.href=HM_HOME_URL;});
  }
  function init(){
    classifyPageLayout();
    installKnownHubLinkFix();
    ensureGlobalBottomNav();
    cleanBloggerArtifacts();
    var homeSearch=bindEmbeddedSearch(),overlay=buildGlobalOverlay(),globalMenu=buildGlobalMenu(),widgetSheet=buildWidgetSheet();
    bindWeatherNavigation(widgetSheet);
    renderUsage();
    bindUsageTracking();
    bindExternal(overlay,homeSearch,globalMenu,widgetSheet);
    if(q("[data-hm-home]")){
      // 이미 파싱 중 시작했으면 재사용하고, 아직이면 즉시 시작한다.
      startHomeCatalog();
    }
    applyInitialQuery(homeSearch,overlay);
    installBackFallback();
    resetStaleUiLayer();
  }
  /* 홈 HTML은 이 스크립트보다 먼저 존재하므로 DOMContentLoaded까지 기다리지 않고 네트워크를 선행한다. */
  if(q("[data-hm-home]"))startHomeCatalog();
  if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",init,{once:true});else init();
})(window,document);
