(function(){
  'use strict';
  function qsa(selector){return Array.prototype.slice.call(document.querySelectorAll(selector));}
  function safeClose(node){
    if(!node)return;
    try{if(node.contains(document.activeElement))document.activeElement.blur();}catch(error){}
    node.classList.remove('is-open','is-detail','is-mobile-quick');
    node.setAttribute('aria-hidden','true');
  }
  function clearTransientLayers(){
    var root=document.documentElement;
    root.classList.remove('hm-ui-layer-open','hm-weather-sheet-open');
    root.style.removeProperty('overflow');
    if(document.body)document.body.style.removeProperty('overflow');
    qsa('.hm-global-menu.is-open,.hm-global-search.is-open,.hm-widget-sheet.is-open').forEach(safeClose);
    var panel=document.querySelector('[data-hm-home-search-panel]');
    if(panel)panel.hidden=true;
  }
  function shouldHandleLink(event,link){
    if(!link||event.defaultPrevented)return false;
    if(link.target&&link.target!=='_self')return false;
    if(event.metaKey||event.ctrlKey||event.shiftKey||event.altKey)return false;
    var href=String(link.getAttribute('href')||'');
    if(!href||href.charAt(0)==='#'||/^javascript:/i.test(href)||/^mailto:|^tel:/i.test(href))return false;
    return true;
  }
  /* 페이지 이탈 시 현재 레이어/하단바 DOM을 건드리지 않는다.
     새 문서 또는 BFCache 복귀가 완료된 뒤에만 transient UI를 정리한다. */
  window.addEventListener('pageshow',function(){clearTransientLayers();});
})();
