(function(){
  'use strict';
  function warmThumbs(){
    if(!document.body||!document.body.classList.contains('is-home'))return;
    var thumbs=[].slice.call(document.querySelectorAll('.index-post .entry-thumb[data-image]'));
    if(!thumbs.length)return;
    var seen=new WeakSet();
    function load(el){
      if(!el||seen.has(el)||el.classList.contains('lazy-ify'))return;
      seen.add(el);
      var src=el.getAttribute('data-image');
      if(!src)return;
      src=String(src)
        .replace(/\/w\d+-h\d+(?:-[^/]+)?\//i,'/s1200/')
        .replace(/\/s\d+(?:-c)?\//i,'/s1200/')
        .replace(/=w\d+-h\d+(?:-[^&]+)?(?:&|$)/i,'=s1200$1')
        .replace(/=s\d+(?:-c)?(?:&|$)/i,'=s1200$1');
      el.setAttribute('data-image',src);
      var img=new Image();
      img.decoding='async';
      img.onload=function(){el.style.backgroundImage='url(\"'+String(src).replace(/\"/g,'%22')+'\")';el.classList.add('lazy-ify');};
      img.src=src;
    }
    /* 첫 행은 즉시, 그 아래는 뷰포트 약 520px 전에 미리 준비 */
    thumbs.slice(0,5).forEach(load);
    if('IntersectionObserver' in window){
      var io=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(entry.isIntersecting){load(entry.target);io.unobserve(entry.target);}});},{rootMargin:'520px 0px'});
      thumbs.slice(5).forEach(function(el){io.observe(el);});
    }else{
      thumbs.slice(5,12).forEach(load);
    }
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',function(){window.setTimeout(warmThumbs,60);},{once:true});
  else window.setTimeout(warmThumbs,60);
})();
