(function(){
  'use strict';

  function clean(value){
    return String(value == null ? '' : value).replace(/\s+/g,' ').trim();
  }

  function stripHtml(value){
    var box=document.createElement('div');
    box.innerHTML=String(value||'');
    return clean(box.textContent||box.innerText||'');
  }

  function alternateUrl(entry){
    var links=entry&&entry.link||[];
    for(var i=0;i<links.length;i++){
      if(links[i]&&links[i].rel==='alternate') return links[i].href||'';
    }
    return '';
  }

  function thumbnail(entry){
    var thumb=entry&&entry.media$thumbnail&&entry.media$thumbnail.url;
    if(!thumb) return '';
    return String(thumb)
      .replace(/\/s72-c\//,'/s640-c/')
      .replace(/=s72-c(?:$|&)/,'=s640-c$1');
  }

  function dateText(value){
    try{
      return new Intl.DateTimeFormat('ko-KR',{year:'numeric',month:'long',day:'numeric'}).format(new Date(value));
    }catch(error){
      return '';
    }
  }

  function makeLabelCard(entry){
    var url=alternateUrl(entry);
    if(!url) return null;

    var article=document.createElement('article');
    article.className='blog-post hentry index-post hm-label-card';

    var image=thumbnail(entry);
    var imageLink=document.createElement('a');
    imageLink.className='hm-label-card-image'+(image?'':' is-empty');
    imageLink.href=url;
    imageLink.setAttribute('aria-label',clean(entry.title&&entry.title.$t)||'웹도구 열기');

    if(image){
      var img=document.createElement('img');
      img.src=image;
      img.alt=clean(entry.title&&entry.title.$t);
      img.loading='lazy';
      img.decoding='async';
      imageLink.appendChild(img);
    }else{
      var icon=document.createElement('i');
      icon.className='bi bi-tools';
      imageLink.appendChild(icon);
    }

    var body=document.createElement('div');
    body.className='hm-label-card-body';

    var title=document.createElement('h2');
    title.className='hm-label-card-title';
    var titleLink=document.createElement('a');
    titleLink.href=url;
    titleLink.textContent=clean(entry.title&&entry.title.$t)||'제목 없는 게시물';
    title.appendChild(titleLink);

    var summary=document.createElement('p');
    summary.className='hm-label-card-summary';
    summary.textContent=stripHtml(
      entry.summary&&entry.summary.$t ||
      entry.content&&entry.content.$t ||
      ''
    ).slice(0,150);

    var date=document.createElement('div');
    date.className='hm-label-card-date';
    date.textContent=dateText(entry.published&&entry.published.$t);

    body.appendChild(title);
    if(summary.textContent) body.appendChild(summary);
    body.appendChild(date);
    article.appendChild(imageLink);
    article.appendChild(body);
    return article;
  }

  function currentLabel(){
    var path=decodeURIComponent(location.pathname||'').replace(/\/+$/,'');
    var prefix='/search/label/';
    if(path.indexOf(prefix)!==0) return '';
    return clean(path.slice(prefix.length));
  }

  function fetchLabelBatch(label,startIndex,maxResults){
    var url='/feeds/posts/summary/-/'+encodeURIComponent(label)
      +'?alt=json&orderby=published&start-index='+startIndex
      +'&max-results='+maxResults;
    return fetch(url,{
      method:'GET',
      credentials:'same-origin',
      cache:'no-store',
      headers:{Accept:'application/json'}
    }).then(function(response){
      if(!response.ok) throw new Error('HTTP '+response.status);
      return response.json();
    });
  }

  function fetchAllLabelPosts(label){
    var pageSize=50,all=[],total=null;
    function next(startIndex){
      return fetchLabelBatch(label,startIndex,pageSize).then(function(data){
        var feed=data&&data.feed||{};
        var entries=feed.entry||[];
        if(total===null){
          total=Number(feed.openSearch$totalResults&&feed.openSearch$totalResults.$t)||0;
        }
        all=all.concat(entries);
        if(entries.length===pageSize && (!total || all.length<total)){
          return next(startIndex+pageSize);
        }
        return all;
      });
    }
    return next(1);
  }

  function installWebtoolsLabelHub(){
    var label=currentLabel();
    if(label!=='웹도구') return;

    document.body.classList.add('hm-webtools-label-hub');

    var grid=document.querySelector('.blog-posts.index-post-wrap');
    if(!grid) return;

    fetchAllLabelPosts(label).then(function(entries){
      var cards=[];
      entries.forEach(function(entry){
        var card=makeLabelCard(entry);
        if(card) cards.push(card);
      });
      if(!cards.length) return;

      var head=document.querySelector('.hm-label-hub-head');
      if(!head){
        head=document.createElement('section');
        head.className='hm-label-hub-head';
        var copy=document.createElement('div');
        var title=document.createElement('h2');
        title.textContent='웹도구 전체';
        var desc=document.createElement('p');
        desc.textContent='힐링편의점에 등록된 웹도구 게시물을 최신순으로 한 번에 확인하세요.';
        copy.appendChild(title);
        copy.appendChild(desc);
        var count=document.createElement('div');
        count.className='hm-label-hub-count';
        count.textContent='전체 '+cards.length+'개';
        head.appendChild(copy);
        head.appendChild(count);
        grid.parentNode.insertBefore(head,grid);
      }

      grid.replaceChildren();
      cards.forEach(function(card){grid.appendChild(card);});

      var pager=document.getElementById('blog-pager');
      if(pager) pager.classList.add('hm-label-hub-complete');
    }).catch(function(){
      /* 실패 시 Blogger 원래 목록과 기존 더보기 기능을 그대로 사용 */
    });
  }

  function buildRelatedFallback(){
    if(!document.body.classList.contains('is-post')) return;

    var wrap=document.getElementById('related-wrap');
    if(!wrap) return;
    var content=wrap.querySelector('.vtrick-pro-related-content');
    if(!content || content.querySelector('.related-item')) return;

    var tag=content.querySelector('.related-tag');
    var label=clean(tag&&tag.getAttribute('data-label'));
    if(label==='HM-Service') label='recent';
    var endpoint=label&&label!=='recent'
      ? '/feeds/posts/summary/-/'+encodeURIComponent(label)+'?alt=json&orderby=published&max-results=10'
      : '/feeds/posts/summary?alt=json&orderby=published&max-results=10';

    fetch(endpoint,{credentials:'same-origin',cache:'no-store',headers:{Accept:'application/json'}})
      .then(function(response){
        if(!response.ok) throw new Error('HTTP '+response.status);
        return response.json();
      })
      .then(function(data){
        if(content.querySelector('.related-item')) return;
        var entries=data&&data.feed&&data.feed.entry||[];
        var current=location.href.replace(/[#?].*$/,'').replace(/\/$/,'');
        var selected=[];
        for(var i=0;i<entries.length && selected.length<6;i++){
          var url=alternateUrl(entries[i]);
          if(!url) continue;
          if(url.replace(/[#?].*$/,'').replace(/\/$/,'')===current) continue;
          selected.push(entries[i]);
        }
        if(!selected.length) return;

        var grid=document.createElement('div');
        grid.className='related-posts hm-related-fallback';

        selected.forEach(function(entry){
          var url=alternateUrl(entry);
          var item=document.createElement('article');
          item.className='related-item';

          var imgLink=document.createElement('a');
          imgLink.className='entry-image-wrap hm-related-image';
          imgLink.href=url;
          var imgUrl=thumbnail(entry);
          if(imgUrl){
            var img=document.createElement('img');
            img.src=imgUrl;
            img.alt=clean(entry.title&&entry.title.$t);
            img.loading='lazy';
            img.decoding='async';
            imgLink.appendChild(img);
          }

          var header=document.createElement('div');
          header.className='entry-header';
          var title=document.createElement('h3');
          title.className='entry-title';
          var a=document.createElement('a');
          a.href=url;
          a.textContent=clean(entry.title&&entry.title.$t)||'게시물';
          title.appendChild(a);

          var meta=document.createElement('div');
          meta.className='entry-meta';
          meta.textContent=dateText(entry.published&&entry.published.$t);

          header.appendChild(title);
          header.appendChild(meta);
          item.appendChild(imgLink);
          item.appendChild(header);
          grid.appendChild(item);
        });

        content.replaceChildren(grid);
      })
      .catch(function(){});
  }

  function init(){
    /* 라벨 페이지는 VTrick/Blogger 원본 목록을 그대로 사용한다. */

    /* 기존 VTrick 추천 로더에 충분한 시간을 준 뒤, 비어 있을 때만 fallback */
    window.setTimeout(buildRelatedFallback,2600);
  }

  if(document.readyState==='loading'){
    document.addEventListener('DOMContentLoaded',init,{once:true});
  }else{
    init();
  }
})();
