(function(){
  'use strict';
  var LIFE_URL='https://www.healing-mart.com/2026/08/life-info.html';
  function norm(value){return String(value||'').trim().toLowerCase().replace(/[\s·ㆍ_\-–—/|()[\]{}.,:;!?]+/g,'');}
  var MAP=[
    {category:'life',title:'생활·살림',labels:['생활·살림','생활정보','생활','생활꿀팁']},
    {category:'health',title:'건강·의료',labels:['건강·의료','건강','의료']},
    {category:'finance',title:'금융·재테크',labels:['금융·재테크','금융','재테크','돈이되는상식']},
    {category:'policy',title:'정부정책·지원금',labels:['정부정책·지원금','정부정책','지원금','민생지원금','지원금·복지','복지']},
    {category:'digital',title:'AI·디지털',labels:['AI·디지털','AI.디지탈','AI.디지털','AI디지털','디지털','AI']},
    {category:'growth',title:'자기계발·커리어',labels:['자기계발·커리어','자기계발','자기개발','자기계발·글쓰기','자기계발.글쓰기','자기계발.커리어','커리어']},
    {category:'culture',title:'상식.교양',labels:['상식.교양','상식·교양','상식','교양']},
    {category:'housing',title:'주거·부동산',labels:['주거·부동산','주거','부동산']},
    {category:'transport',title:'자동차·교통',labels:['자동차·교통','자동차','교통']},
    {category:'travel',title:'여행·여가',labels:['여행·여가','여행','여가']}
  ];
  function classify(label){
    var n=norm(label);if(!n)return null;
    if(n.indexOf(norm('자기계발'))!==-1||n.indexOf(norm('자기개발'))!==-1)return {title:'자기계발·커리어',category:'growth'};
    for(var i=0;i<MAP.length;i++)for(var j=0;j<MAP[i].labels.length;j++)if(n===norm(MAP[i].labels[j]))return MAP[i];
    return null;
  }
  function labelFromAnchor(a){
    var text=(a.textContent||'').trim();
    try{var u=new URL(a.href,location.href),m=decodeURIComponent(u.pathname).match(/\/search\/label\/(.+)$/);if(m&&m[1])return m[1];}catch(e){}
    return text;
  }
  function fix(root){
    var scope=root&&root.querySelectorAll?root:document;
    var links=scope.querySelectorAll('.entry-labels a[href*="/search/label/"], .post-labels a[href*="/search/label/"], a[rel="tag"][href*="/search/label/"]');
    var seenByParent=new WeakMap();
    Array.prototype.forEach.call(links,function(a){
      var label=labelFromAnchor(a);
      if(norm(label)===norm('HM-Service')){a.hidden=true;return;}
      var mapped=classify(label);if(!mapped)return;
      var parent=a.parentElement;
      if(parent){
        var seen=seenByParent.get(parent);if(!seen){seen={};seenByParent.set(parent,seen);}
        if(seen[mapped.category]){a.hidden=true;return;}
        seen[mapped.category]=1;
      }
      a.textContent=mapped.title;
      a.href=LIFE_URL+'?category='+mapped.category;
      a.setAttribute('data-hm-canonical-category',mapped.category);
    });
  }
  function init(){
    fix(document);
    if(!window.MutationObserver)return;
    var observer=new MutationObserver(function(mutations){mutations.forEach(function(m){Array.prototype.forEach.call(m.addedNodes||[],function(node){if(node&&node.nodeType===1)fix(node);});});});
    observer.observe(document.body,{childList:true,subtree:true});
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();
})();
